VAR submit_btn_visible = true
VAR submit_btn_scale = 1.0

IMAGE submit_btn "submit_btn" x=300 y=500 w=120 h=40 z=1 vis=submit_btn_visible parent=canvas rot=0 animation={}

STYLE submit_btn {"display":"none","scale":submit_btn_scale,"alpha":1}

ON submit_btn_visible "toggle_visibility"
    VAR submit_btn_visible = !submit_btn_visible
    IF submit_btn_visible
        STYLE submit_btn {"display":"block","scale":1.0,"alpha":1}
    ELSE
        STYLE submit_btn {"display":"none","scale":0.0,"alpha":0}
    END

ON submit_btn_scale "toggle_scale"
    VAR submit_btn_scale = (submit_btn_scale == 1.0) ? 0.8 : 1.0
    STYLE submit_btn {"scale":submit_btn_scale}

AUTO "init"
    STYLE submit_btn {"display":"block","scale":1.0,"alpha":1}

VAR story_text = "请问刚才出现的农具是以下哪一个？"
SIGNAL answer "收到answer信号"
    TEXT story_text "请问刚才出现的农具是以下哪一个？" x=20 y=20 z=10
    BGM 1001-___1 vol=0.8 loop=true fade=0.5
    BUTTON submit-btn "提交" x=20 y=400 w=100 h=50 vis=false
    BUTTON submit-btn2 "提交" x=20 y=400 w=100 h=50 vis=true
    IMAGE show_image_1 "__01" x=150 y=150 w=120 h=120 z=5 vis=true rot=0 animation={"entry":{"animId":"__05"},"loop":{"animId":"__05"}}
    IMAGE show_image_2 "__05" x=300 y=150 w=120 h=120 z=5 vis=true rot=0 animation={"entry":{"animId":"__05"},"loop":{"animId":"__05"}}
    SELECT show_image_1 enabled=true var=card1_selected single=true overlay=check-circle effect=pulse
    STYLE show_image_1 {"display":"block","scale":1.0,"alpha":1.0}
    STYLE show_image_2 {"display":"block","scale":1.0,"alpha":1.0}
